    /**
     * Method to retrieve the Facility via an FindFacilityQuery
     * @return 	query	FindFacilityQuery
     */
    @SuppressWarnings("unused")
    public Facility find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Facility - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Facilitys
     *
     * @param	query	FindAllFacilityQuery 
     * @return 	List<Facility> 
     */
    @SuppressWarnings("unused")
    public List<Facility> findAll( FindAllFacilityQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Facility - {0}", exc.getMessage() );
    	}
    	return null;
    }


